// REVIEW PROBE (throwaway, deleted after the run): /provider import decline
// must leave the imported entry present-but-INACTIVE per the flow's own
// message ("keeping the current provider").
import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/cli/paste_image.dart';
import 'package:flutter_agent_harness/src/providers/fahx_codec.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

String? clipboardBox;

CustomProviderEntry _acmeEntry() => CustomProviderEntry(
  name: 'acme',
  apiType: 'openai',
  baseUrl: 'https://api.acme.io/v1',
  modelId: 'glm-4.6',
  keyName: 'FA_KEY_API_ACME_IO',
);

const _acmeKey = 'sk-acme-raw';

void main() {
  late MemoryExecutionEnv env;
  late FakeCliIO io;
  late FakeCliIO ioB;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    io = FakeCliIO();
    ioB = FakeCliIO();
    clipboardBox = null;
  });

  tearDown(() async {
    await io.close();
    await ioB.close();
  });

  test('probe: import decline leaves _activeCustomName pointing at the import', () async {
    final entry = _acmeEntry();
    final storeA = FakeSecureKeyStore()..map['FA_KEY_API_ACME_IO'] = _acmeKey;
    final cacheA = SecureKeyCache(storeA);
    await cacheA.preload(const ['FA_KEY_API_ACME_IO']);
    final cliA = AgentCli(
      config: AgentCliConfig(
        model: Model(
          id: entry.modelId,
          api: 'openai-completions',
          provider: 'openai',
          baseUrl: entry.baseUrl,
          contextWindow: 200000,
          maxTokens: 16384,
        ),
        apiKey: 'k',
        env: env,
        sessionRoot: '/sessions',
        secureKeys: cacheA,
        customProviders: CustomProviderRegistry([entry]),
        activeCustomName: 'acme',
        clipboardWrite: (text) async {
          clipboardBox = text;
          return null;
        },
      ),
      io: io,
      streamFunction: FakeStreamFunction([textTurn('ok')]).call,
    );
    final runA = cliA.run();
    io.sendLine('/provider export --yes');
    while (!io.out.toString().contains('export passphrase')) {
      await Future<void>.delayed(const Duration(milliseconds: 10));
    }
    io.sendLine('pass-phrase-1');
    while (!io.out.toString().contains('confirm passphrase')) {
      await Future<void>.delayed(const Duration(milliseconds: 10));
    }
    io.sendLine('pass-phrase-1');
    while (!io.out.toString().contains('container copied to clipboard')) {
      await Future<void>.delayed(const Duration(milliseconds: 10));
    }
    io.sendLine('/exit');
    await runA;

    // Machine B: runs a DIFFERENT live provider (catalog preset, no active
    // custom entry), imports acme, DECLINES the switch.
    final registryB = CustomProviderRegistry([]);
    final storeB = FakeSecureKeyStore();
    final cacheB = SecureKeyCache(storeB);
    await cacheB.probe();
    final cliB = AgentCli(
      config: AgentCliConfig(
        model: testModel,
        apiKey: 'k',
        env: env,
        sessionRoot: '/sessions',
        secureKeys: cacheB,
        customProviders: registryB,
        clipboardRead: () async => PasteboardText(clipboardBox!),
      ),
      io: ioB,
      streamFunction: FakeStreamFunction([textTurn('ok')]).call,
    );
    final runB = cliB.run();
    ioB.sendLine('/provider import');
    while (!ioB.out.toString().contains('container passphrase')) {
      await Future<void>.delayed(const Duration(milliseconds: 10));
    }
    ioB.sendLine('pass-phrase-1');
    while (!ioB.out.toString().contains('imported provider acme')) {
      await Future<void>.delayed(const Duration(milliseconds: 10));
    }
    ioB.sendLine('n');
    while (!ioB.out.toString().contains('keeping the current provider')) {
      await Future<void>.delayed(const Duration(milliseconds: 10));
    }
    ioB.sendLine('/exit');
    await runB;

    // EXPECTED per the decline message + AC8: the imported entry stays
    // present but NOT active; the live model (testModel) keeps running.
    final actual = cliB.activeCustomProviderName;
    expect(registryB.find('acme'), isNotNull, reason: 'entry lands in the registry');
    // ignore: avoid_print
    print('PROBE activeCustomProviderName after decline: $actual');
    expect(actual, isNull, reason: 'decline must keep the current provider active');
  });
}

